          "type": "text",
          "text": "from collections import Counter, deque\n\ndef transform(grid):\n    h, w = len(grid), len(grid[0])\n    counts = Counter(v for row in grid for v in row)\n    bg = counts.most_common(1)[0][0]\n    fg = next(v for v in counts if v != bg)\n    out = [row[:] for row in grid]\n    seen = set()\n    for r in range(h):\n        for c in range(w):\n            if grid[r][c] != bg or (r, c) in seen:\n                continue\n            q = deque([(r, c)])\n            seen.add((r, c))\n            component = []\n            touches_edge = False\n            while q:\n                y, x = q.popleft()\n                component.append((y, x))\n                if y in (0, h - 1) or x in (0, w - 1):\n                    touches_edge = True\n                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n                    ny, nx = y + dy, x + dx\n                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg\n                            and (ny, nx) not in seen):\n                        seen.add((ny, nx))\n                        q.append((ny, nx))\n            if not touches_edge:\n                for y, x in component:\n                    out[y][x] = 4\n    return out"
        }
