from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Fill zero-valued components that are enclosed by the nonzero drawing.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                edge |= y == 0 or y == h - 1 or x == 0 or x == w - 1
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            if not edge:
                for y, x in cells:
                    out[y][x] = 4
    # A solid 3x3 block of color 2 is the marked object in the demonstration.
    for r in range(h - 2):
        for c in range(w - 2):
            if all(grid[y][x] == 2 for y in range(r,r+3) for x in range(c,c+3)):
                for y in range(r,r+3):
                    for x in range(c,c+3): out[y][x] = 4
    return out
